-- KIDOO schema for Turso (libSQL / SQLite).
-- Replaces the old Supabase (Postgres) schema. Authorization (formerly RLS) is enforced in
-- the application layer: see lib/backend/policies.ts.
--
-- Conventions
--   * ids are UUID v4 strings (default generated by SQLite when omitted)
--   * timestamps are ISO-8601 UTC strings, e.g. 2026-10-31T18:03:45.123Z
--   * booleans are INTEGER 0/1 (the query layer converts them back to true/false)
--   * jsonb columns are TEXT holding JSON

-- ---------------------------------------------------------------------------
-- Auth (replaces auth.users)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  email TEXT NOT NULL UNIQUE,
  encrypted_password TEXT,
  email_confirmed_at TEXT,
  raw_app_meta_data TEXT NOT NULL DEFAULT '{}',
  raw_user_meta_data TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_sign_in_at TEXT
);

CREATE TABLE IF NOT EXISTS platform_admins (
  user_id TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS password_resets (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL,
  used_at TEXT
);

CREATE INDEX IF NOT EXISTS password_resets_user_idx ON password_resets (user_id);

-- ---------------------------------------------------------------------------
-- Domain tables
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS families (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 2 AND 80),
  plan TEXT NOT NULL DEFAULT 'free' CHECK (plan IN ('free', 'family', 'plus')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  reward_mode TEXT NOT NULL DEFAULT 'points' CHECK (reward_mode IN ('points', 'symbolic', 'allowance')),
  points_per_currency REAL,
  currency_amount REAL,
  reward_note TEXT,
  location_24h_enabled INTEGER NOT NULL DEFAULT 0,
  lgpd_accepted_at TEXT,
  kids_access_key TEXT,
  parent_access_key TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE UNIQUE INDEX IF NOT EXISTS families_kids_access_key_uidx
  ON families (kids_access_key) WHERE kids_access_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS families_parent_access_key_uidx
  ON families (parent_access_key) WHERE parent_access_key IS NOT NULL;

CREATE TABLE IF NOT EXISTS profiles (
  id TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('owner', 'parent', 'child')),
  display_name TEXT NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 60),
  age_group TEXT CHECK (age_group IN ('6_9', '10_13', '14_plus')),
  invite_code TEXT UNIQUE,
  pin_hash TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX IF NOT EXISTS profiles_family_id_idx ON profiles (family_id);

CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  created_by TEXT NOT NULL REFERENCES profiles (id),
  assigned_child_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  kind TEXT NOT NULL DEFAULT 'points' CHECK (kind IN ('points', 'reminder')),
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 80),
  description TEXT,
  weight INTEGER NOT NULL DEFAULT 1 CHECK (weight >= 0 AND weight <= 20),
  due_at TEXT,
  require_photo INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'awaiting_approval', 'completed', 'expired')),
  score_applied INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX IF NOT EXISTS tasks_family_status_idx ON tasks (family_id, status);
CREATE INDEX IF NOT EXISTS tasks_child_idx ON tasks (assigned_child_id, status);

CREATE TABLE IF NOT EXISTS task_completions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  task_id TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
  child_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  photo_key TEXT,
  storage_provider TEXT NOT NULL DEFAULT 'r2' CHECK (storage_provider IN ('supabase', 'r2')),
  lat REAL,
  lng REAL,
  location_available INTEGER NOT NULL DEFAULT 0,
  captured_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  approved_by TEXT REFERENCES profiles (id),
  approved_at TEXT,
  rejected_at TEXT,
  rejection_note TEXT,
  points_awarded INTEGER,
  child_note TEXT CHECK (child_note IS NULL OR length(trim(child_note)) <= 280),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX IF NOT EXISTS completions_family_idx ON task_completions (family_id, created_at DESC);
CREATE INDEX IF NOT EXISTS completions_task_idx ON task_completions (task_id);

CREATE TABLE IF NOT EXISTS monthly_scores (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  child_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  year INTEGER NOT NULL,
  month INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12),
  credits INTEGER NOT NULL DEFAULT 0,
  debits INTEGER NOT NULL DEFAULT 0,
  balance INTEGER GENERATED ALWAYS AS (credits + debits) STORED,
  UNIQUE (child_id, year, month)
);

CREATE TABLE IF NOT EXISTS platform_settings (
  id INTEGER PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  plan_limits TEXT NOT NULL DEFAULT '{"free":{"children":1,"tasks_per_month":10,"photo_retention_days":15},"family":{"children":4,"tasks_per_month":null,"photo_retention_days":15},"plus":{"children":null,"tasks_per_month":null,"photo_retention_days":15}}',
  feature_flags TEXT NOT NULL DEFAULT '{"location_24h":false,"geofencing":false,"auto_approve":false}',
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

INSERT OR IGNORE INTO platform_settings (id) VALUES (1);

CREATE TABLE IF NOT EXISTS child_live_locations (
  child_id TEXT PRIMARY KEY REFERENCES profiles (id) ON DELETE CASCADE,
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  lat REAL NOT NULL,
  lng REAL NOT NULL,
  accuracy_m REAL,
  heading REAL,
  speed_mps REAL,
  captured_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  sharing INTEGER NOT NULL DEFAULT 1,
  source TEXT NOT NULL DEFAULT 'pwa_foreground' CHECK (source IN ('pwa_foreground', 'native_background'))
);

CREATE INDEX IF NOT EXISTS child_live_locations_family_idx
  ON child_live_locations (family_id, captured_at DESC);

CREATE TABLE IF NOT EXISTS child_location_tokens (
  token_hash TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_used_at TEXT
);

CREATE INDEX IF NOT EXISTS child_location_tokens_child_idx ON child_location_tokens (child_id);

CREATE TABLE IF NOT EXISTS push_subscriptions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  endpoint TEXT NOT NULL,
  p256dh TEXT NOT NULL,
  auth TEXT NOT NULL,
  user_agent TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (user_id, endpoint)
);

CREATE INDEX IF NOT EXISTS push_subscriptions_user_id_idx ON push_subscriptions (user_id);

CREATE TABLE IF NOT EXISTS allowance_payouts (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', abs(random()) % 4 + 1, 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  family_id TEXT NOT NULL REFERENCES families (id) ON DELETE CASCADE,
  child_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  year INTEGER NOT NULL,
  month INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12),
  amount REAL NOT NULL CHECK (amount > 0),
  paid_by TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX IF NOT EXISTS allowance_payouts_family_month_idx ON allowance_payouts (family_id, year, month);
CREATE INDEX IF NOT EXISTS allowance_payouts_child_month_idx ON allowance_payouts (child_id, year, month, created_at DESC);

-- ---------------------------------------------------------------------------
-- Keep the app claims on users in sync with the profile (was a Postgres trigger).
-- ---------------------------------------------------------------------------

CREATE TRIGGER IF NOT EXISTS profiles_sync_claims_insert
AFTER INSERT ON profiles
BEGIN
  UPDATE users
  SET raw_app_meta_data = json_set(
    COALESCE(NULLIF(raw_app_meta_data, ''), '{}'),
    '$.role', NEW.role,
    '$.family_id', NEW.family_id,
    '$.platform_admin',
      CASE WHEN json_extract(COALESCE(NULLIF(raw_app_meta_data, ''), '{}'), '$.platform_admin') IN (1, 'true')
        THEN json('true') ELSE json('false') END
  )
  WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS profiles_sync_claims_update
AFTER UPDATE OF role, family_id ON profiles
BEGIN
  UPDATE users
  SET raw_app_meta_data = json_set(
    COALESCE(NULLIF(raw_app_meta_data, ''), '{}'),
    '$.role', NEW.role,
    '$.family_id', NEW.family_id,
    '$.platform_admin',
      CASE WHEN json_extract(COALESCE(NULLIF(raw_app_meta_data, ''), '{}'), '$.platform_admin') IN (1, 'true')
        THEN json('true') ELSE json('false') END
  )
  WHERE id = NEW.id;
END;
